CHAVE = b"chave-secreta-de-demonstracao"  # produção: cofre
def mascarar(texto, achados, modo="rotulo"):
    for ini, fim, tipo in sorted(achados, reverse=True):
        if modo == "rotulo": sub = f"[{tipo}]"
        else: sub = f"<{tipo}:" + hmac.new(CHAVE,
            texto[ini:fim].lower().encode(), "sha256").hexdigest()[:8] + ">"
        texto = texto[:ini] + sub + texto[fim:]
    return texto
